    def loss(p):
        f=_linear(np.sin(p[0]*u)**2);return (f@np.linalg.lstsq(f,v,rcond=None)[0]-v).ravel()
    freq=least_squares(loss,[1.2],bounds=(.65,1.65)).x[0]
    columns=[]
