        p=minimize(evaluate,np.r_[np.full(len(K),-4.),-6.],jac=True,method='L-BFGS-B',bounds=[(-17,6)]*len(K)+[(-11,-1)],options={'maxiter':160,'ftol':1e-8}).x
        out.append(evaluate(p,True))
