            else:
                d=A.diagonal(); ax=A@(err/d); D=(-2*np.outer(ax,a)+2*(A*(err**2/d)[None,:])@A)/n; loss=np.mean(err**2)
            return loss,w*np.r_[F@D.ravel(),np.trace(D)]
