    scale = np.maximum(h.std(axis=0), 1e-8)
    h = (h-center)/scale
    mean = targets.mean(axis=0)
    w = np.linalg.solve(h.T @ h + 0.02*np.eye(h.shape[1]), h.T @ (targets-mean))
    return (ht-center)/scale @ w + mean


